// ── Humanoid Figure ──────────────────────────────────────────────
const humanoid = new THREE.Group();
scene.add(humanoid);

// Color palette
const skinColor = 0xd4b896;
const skinLight = 0xe8d4b0;
const skinDark = 0xb89a78;
const skinMid = 0xc4a888;
const skinPalm = 0xe4c8a8;
const skinNail = 0x8a7a6a;
const skinEyes = 0x1a1a2e;
const skinPupil = 0x0a0a1a;
const skinLip = 0x8a5a5a;
const skinNostril = 0x5a4a3a;
const skinBrows = 0x6a5a4a;
const skinEyelid = 0xd4b896;
const skinEyelidInner = 0xc4a888;

const skinMaterial = {
  color: skinColor,
  roughness: 0.5,
  metalness: 0.0,
  side: THREE.DoubleSide,
  transparent: false,
};
const skinMaterialHead = { ...skinMaterial, roughness: 0.4, metalness: 0.05 };
const skinMaterialInner = { ...skinMaterial, roughness: 0.6, metalness: 0.0 };
const skinMaterialLip = { color: skinLip, roughness: 0.3, metalness: 0.0 };
const skinMaterialBrow = { color: skinBrows, roughness: 0.8, metalness: 0.0 };
const skinMaterialEyelid = { color: skinEyelid, roughness: 0.6, metalness: 0.0 };
const skinMaterialEyelidInner = { color: skinEyelidInner, roughness: 0.7, metalness: 0.0 };
const skinMaterialEyeball = { color: skinEyes, roughness: 0.3, metalness: 0.0 };
const skinMaterialPupil = { color: skinPupil, roughness: 0.2, metalness: 0.0 };
const skinMaterialPalm = { color: skinPalm, roughness: 0.5, metalness: 0.0 };
