const skinMaterialElbow = { color: skinDark, roughness: 0.6, metalness: 0.0 };
const skinMaterialShoulder = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialNeck = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialTorso = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialAbdomen = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialLeg = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialCalf = { color: skinMid, roughness: 0.5, metalness: 0.0 };
const skinMaterialFoot = { color: skinDark, roughness: 0.6, metalness: 0.0 };
