// ── Helper: create cylinder ────────────────────────────────────────
function createCylinder(radius, height, material, x, y, z, rotationX = 0, rotationY = 0) {
  const geo = new THREE.CylinderGeometry(radius, radius * 0.9, height, 8, 1);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  return mesh;
}

// ── Helper: create capsule (rounded cylinder) ─────────────────────
function createCapsule(length, radius, material, x, y, z, rotationX = 0, rotationY = 0, rotationZ = 0) {
  const geo = new THREE.CylinderGeometry(radius, radius, length, 8, 1);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  mesh.rotation.z = rotationZ;
  return mesh;
}

// ── Helper: create box ─────────────────────────────────────────────
function createBox(w, h, d, material, x, y, z, rotationX = 0, rotationY = 0, rotationZ = 0) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  mesh.rotation.z = rotationZ;
  return mesh;
}

// ── Helper: create sphere ──────────────────────────────────────────
function createSphere(radius, material, x, y, z, rotationX = 0, rotationY = 0, rotationZ = 0) {
  const geo = new THREE.SphereGeometry(radius, 8, 8);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  mesh.rotation.z = rotationZ;
  return mesh;
}

// ── Helper: create plane ───────────────────────────────────────────
function createPlane(width, depth, material, x, y, z, rotationX = 0, rotationY = 0, rotationZ = 0) {
  const geo = new THREE.PlaneGeometry(width, depth, 4, 4);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  mesh.rotation.z = rotationZ;
  return mesh;
}

// ── Helper: create box with custom geometry ────────────────────────
function createBoxCustom(w, h, d, material, x, y, z, rotationX = 0, rotationY = 0, rotationZ = 0) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rotationX;
  mesh.rotation.y = rotationY;
  mesh.rotation.z = rotationZ;
  return mesh;
}

// ── Build Humanoid ────────────────────────────────────────────────
