humanoid.add(rightPalm);
// Right thumb
const rightThumb = createCapsule(0.08, 0.12, skinThumb, 0.05, 2.12, 0.0, 0, 0, 0);
humanoid.add(rightThumb);
// Right index
const rightIndex = createCapsule(0.08, 0.12, skinIndex, 0.05, 2.12, 0.0, 0, 0, 0);
humanoid.add(rightIndex);
// Right middle
const rightMiddle = createCapsule(0.08, 0.12, skinMiddle, 0.05, 2.12, 0.0, 0, 0, 0);
humanoid.add(rightMiddle);
// Right ring
const rightRing = createCapsule(0.08, 0.12, skinRing, 0.05, 2.12, 0.0, 0, 0, 0);
humanoid.add(rightRing);
// Right pinky
const rightPinky = createCapsule(0.08, 0.12, skinPinky, 0.05, 2.12, 0.0, 0, 0, 0);
humanoid.add(rightPinky);

// Left shoulder
const leftShoulder = createCapsule(0.6, 0.18, skinShoulder, -0.05, 1.6, 0.0, 0, 0, 0);
humanoid.add(leftShoulder);
// Left bicep
